export interface StrokePoint {
  x: number;
  y: number;
}

export type StrokeType =
  | 'horizontal'
  | 'vertical'
  | 'slant_left'
  | 'slant_right'
  | 'corner_right_down'
  | 'dot';

export interface StrokeDefinition {
  index: number;
  name: string;
  hint: string;
  path: string; // SVG path d on a 109x109 viewBox
  start: StrokePoint; // Green start dot
  end: StrokePoint;   // Pink/Red end dot
  type: StrokeType;
}

export interface KanjiStrokeData {
  character: string;
  strokes: StrokeDefinition[];
}

