/**
 * Returns stroke definitions for a kanji character.
 * Uses exact KanjiVG vectors if available, otherwise generates a procedural template.
 */
export function getKanjiStrokes(character: string, strokeCount = 4): StrokeDefinition[] {
  if (KANJI_STROKE_MAP[character] && KANJI_STROKE_MAP[character].length > 0) {
    return KANJI_STROKE_MAP[character];
  }

  // Fallback procedural strokes with cross-hatch structure for unknown kanji
  const count = Math.max(1, strokeCount);
  const fallbackStrokes: StrokeDefinition[] = [];
  for (let i = 0; i < count; i++) {
    const isVertical = i % 2 === 1;
    const progress = (i + 1) / (count + 1);
    const pos = Math.round((20 + progress * 69) * 10) / 10;

    if (isVertical) {
      fallbackStrokes.push({
        index: i,
        name: `Stroke ${i + 1} (Vertical)`,
        hint: 'Draw downward vertical stroke',
        path: `M ${pos} 20 L ${pos} 89`,
        start: { x: pos, y: 20 },
        end: { x: pos, y: 89 },
        type: 'vertical',
      });
    } else {
      fallbackStrokes.push({
        index: i,
        name: `Stroke ${i + 1} (Horizontal)`,
        hint: 'Draw left-to-right horizontal stroke',
        path: `M 20 ${pos} L 89 ${pos}`,
        start: { x: 20, y: pos },
        end: { x: 89, y: pos },
        type: 'horizontal',
      });
    }
  }

  return fallbackStrokes;
}

/**
 * Validates a user-drawn stroke against the expected stroke definition.
 */
export function validateDrawnStroke(
  points: StrokePoint[],
  expected: StrokeDefinition,
  stage: 'guided' | 'outline' | 'blank' = 'guided'
): { valid: boolean; message?: string } {
  if (!points || points.length < 2) {
    return { valid: false, message: 'Stroke too short. Try again.' };
  }

  const start = points[0];
  const end = points[points.length - 1];
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const distance = Math.hypot(dx, dy);

  // Check minimum stroke length (viewBox 0..109)
  if (distance < 5) {
    return { valid: false, message: 'Stroke is too short. Please draw the full stroke.' };
  }

  // Check starting position tolerance (more lenient in blank memory mode)
  const maxStartDist = stage === 'blank' ? 52 : 42;
  const startDist = Math.hypot(start.x - expected.start.x, start.y - expected.start.y);

  if (startDist > maxStartDist) {
    return {
      valid: false,
      message: `Started too far off (${expected.name}). Start near the designated point.`,
    };
  }

  // Direction and orientation validation
  switch (expected.type) {
    case 'horizontal': {
      if (dx < -6) {
        return {
          valid: false,
          message: 'Incorrect direction: Horizontal strokes must be drawn from left to right.',
        };
      }
      if (Math.abs(dy) > Math.abs(dx) * 1.5) {
        return {
          valid: false,
          message: 'Incorrect orientation: This stroke must be horizontal, not vertical!',
        };
      }
      break;
    }

    case 'vertical': {
      if (dy < -6) {
        return {
          valid: false,
          message: 'Incorrect direction: Vertical strokes must be drawn from top to bottom.',
        };
      }
      if (Math.abs(dx) > Math.abs(dy) * 1.5) {
        return {
          valid: false,
          message: 'Incorrect orientation: This stroke must be vertical, not horizontal!',
        };
      }
      break;
    }

    case 'slant_left': {
      if (dy < -6) {
        return {
          valid: false,
          message: 'Incorrect direction: Sweep downwards, not upwards.',
        };
      }
      if (dx > 10) {
        return {
          valid: false,
          message: 'Incorrect direction: This stroke sweeps down to the left, not right.',
        };
      }
      break;
    }

    case 'slant_right': {
      if (dy < -6) {
        return {
          valid: false,
          message: 'Incorrect direction: Sweep downwards, not upwards.',
        };
      }
      if (dx < -10) {
        return {
          valid: false,
          message: 'Incorrect direction: This stroke sweeps down to the right, not left.',
        };
      }
      break;
    }

    case 'corner_right_down': {
      if (dy < -6) {
        return {
          valid: false,
          message: 'Incorrect direction: Fold across top to right and then down.',
        };
      }
      break;
    }

    case 'dot': {
      break;
    }
  }

  return { valid: true };
}
